/**
 * Parsers for the React Spectrum (react-spectrum.adobe.com) and React Aria (react-aria.adobe.com)
 * documentation as published for machines: `llms.txt` (page index) and per-page markdown
 * (`<Page>.md`, generated by the docs site from the repo MDX and the TypeScript API), plus the
 * page MDX sources in adobe/react-spectrum (metadata exports only: version, description,
 * relatedPages). Line-based scanning: API tables contain unescaped `|` inside code spans, which a
 * GFM table parser would split, so table rows are split with code-span awareness. Nothing is executed.
 */
import { collapse, cmp } from "./shared";

/* -------------------------------- llms.txt -------------------------------- */

export interface LlmsEntry {
  title: string;
  /** Path relative to the site root, without ".md" (e.g. "Button", "Button/useButton", "blog/x"). */
  page: string;
  description: string | null;
}

export function parseLlms(text: string): LlmsEntry[] {
  const out: LlmsEntry[] = [];
  const seen = new Set<string>();
  for (const line of text.split(/\r?\n/)) {
    const m = /^\s*-\s*\[([^\]]+)\]\(([^)\s]+?)\.md\)\s*(?::\s*(.*))?$/.exec(line);
    if (!m) continue;
    const page = m[2]!.replace(/^\.\//, "");
    if (/^(https?:|\.\.\/)/.test(page) || seen.has(page)) continue;
    seen.add(page);
    const d = m[3] ? collapse(m[3]) : "";
    out.push({ title: collapse(m[1]!), page, description: d && !d.startsWith("<") ? d : null });
  }
  return out.sort((a, b) => cmp(a.page, b.page));
}

/** Top-level PascalCase component pages ("Button", "ComboBox"), not guides/blog/hook pages. */
export const isComponentPage = (page: string) => /^[A-Z][A-Za-z0-9]+$/.test(page);
/** Hook pages nested under a component page, e.g. "Button/useButton". */
export const hookPageOf = (page: string): { component: string; hook: string } | null => {
  const m = /^([A-Z][A-Za-z0-9]+)\/(use[A-Z][A-Za-z0-9]+)$/.exec(page);
  return m ? { component: m[1]!, hook: m[2]! } : null;
};

/* ---------------------------- markdown scanning ---------------------------- */

export type MdBlock =
  | { type: "heading"; depth: number; text: string; line: number }
  | { type: "code"; lang: string | null; value: string; line: number }
  | { type: "table"; header: string[]; rows: string[][]; line: number }
  | { type: "para"; text: string; line: number };

/** Split a markdown table row on `|`, ignoring pipes inside backtick code spans and escaped pipes. */
export function splitRow(line: string): string[] {
  const s = line.trim().replace(/^\|/, "").replace(/\|$/, "");
  const cells: string[] = [];
  let cur = "";
  let tick = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i]!;
    if (ch === "\\" && s[i + 1] === "|") {
      cur += "|";
      i++;
      continue;
    }
    if (ch === "`") tick = !tick;
    if (ch === "|" && !tick) {
      cells.push(cur.trim());
      cur = "";
      continue;
    }
    cur += ch;
  }
  cells.push(cur.trim());
  return cells;
}

export function scanMarkdown(md: string): MdBlock[] {
  const lines = md.split(/\r?\n/);
  const out: MdBlock[] = [];
  let para: string[] = [];
  let paraLine = 0;
  const flush = () => {
    if (para.length) {
      const t = collapse(para.join(" "));
      if (t && !/^<[A-Za-z/]/.test(t) && !/^\{\/?\*/.test(t)) out.push({ type: "para", text: t, line: paraLine });
    }
    para = [];
  };
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]!;
    const fence = /^(\s*)(```+|~~~+)\s*([A-Za-z0-9_+-]*)/.exec(line);
    if (fence) {
      flush();
      const marker = fence[2]!;
      const body: string[] = [];
      const start = i + 1;
      for (i++; i < lines.length && !lines[i]!.trim().startsWith(marker); i++) body.push(lines[i]!);
      out.push({ type: "code", lang: fence[3] || null, value: body.join("\n"), line: start });
      continue;
    }
    const h = /^(#{1,6})\s+(.*?)\s*#*\s*$/.exec(line);
    if (h) {
      flush();
      out.push({ type: "heading", depth: h[1]!.length, text: cleanInline(h[2]!), line: i + 1 });
      continue;
    }
    if (/^\s*\|/.test(line) && i + 1 < lines.length && /^\s*\|?\s*:?-{2,}/.test(lines[i + 1]!)) {
      flush();
      const header = splitRow(line).map(cleanInline);
      const rows: string[][] = [];
      const start = i + 1;
      for (i += 2; i < lines.length && /^\s*\|/.test(lines[i]!); i++) rows.push(splitRow(lines[i]!));
      i--;
      out.push({ type: "table", header, rows, line: start });
      continue;
    }
    if (!line.trim()) {
      flush();
      continue;
    }
    if (!para.length) paraLine = i + 1;
    para.push(line.trim());
  }
  flush();
  return out;
}

/** Markdown inline -> plain text (links keep their text, code ticks and emphasis removed). */
export function cleanInline(s: string): string {
  return collapse(
    s
      .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
      .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
      .replace(/`([^`]*)`/g, "$1")
      .replace(/\\\*/g, "*")
      .replace(/\*\*([^*]+)\*\*/g, "$1")
      .replace(/<\/?[A-Za-z][^>]*>/g, ""),
  );
}

/** Links to other docs pages ("Link.md", "../Menu.md#x") in prose, as page names. */
export function pageLinks(s: string): string[] {
  const out = new Set<string>();
  for (const m of s.matchAll(/\]\((?:\.\.\/|\.\/)?([A-Z][A-Za-z0-9]+)\.md(?:[#?][^)]*)?\)/g)) out.add(m[1]!);
  return [...out];
}

/* ------------------------------ docs pages -------------------------------- */

export interface MdProp {
  name: string;
  type: string | null;
  defaultValue: string | null;
  required: boolean;
  description: string | null;
  allowedValues: string[] | null;
}

export interface MdApiSection {
  /** Export / type the table documents ("Button", "ComboBoxItem", "AriaButtonOptions"). */
  name: string;
  props: MdProp[];
  line: number;
}

export interface MdSection {
  title: string;
  depth: number;
  firstParagraph: string | null;
  line: number;
  code: { lang: string | null; value: string }[];
}

export interface MdPage {
  title: string | null;
  description: string | null;
  sections: MdSection[];
  /** <InlineAlert><Heading>…</Heading><Content>…</Content></InlineAlert> callouts outside code (only when present). */
  callouts?: { title: string; text: string }[];
  api: MdApiSection[];
  /** Component pages linked from prose (outside code). */
  links: string[];
  /** Import specifiers seen in code examples, e.g. "@react-spectrum/s2/Button". */
  imports: string[];
}

/** `"accent" | "negative" | undefined` -> ["accent","negative"]; null when the type is not a pure literal union. */
export function literalUnion(type: string | null): string[] | null {
  if (!type) return null;
  const parts = type.split("|").map((p) => p.trim()).filter((p) => p && p !== "undefined" && p !== "null");
  if (!parts.length || !parts.every((p) => /^"[^"]*"$|^'[^']*'$/.test(p))) return null;
  return parts.map((p) => p.slice(1, -1));
}

function readPropRow(header: string[], row: string[]): MdProp | null {
  const h = header.map((x) => x.toLowerCase());
  const at = (k: string) => {
    const i = h.indexOf(k);
    return i >= 0 ? (row[i] ?? "") : "";
  };
  const rawName = at("name");
  const nm = /`([^`]+)`/.exec(rawName)?.[1] ?? cleanInline(rawName);
  const name = nm.trim();
  if (!name || name.length > 80) return null;
  const required = /\\\*|\*\s*$/.test(rawName.replace(/`[^`]*`/g, ""));
  const rawType = at("type");
  const type = rawType ? (/^`([\s\S]*)`$/.exec(rawType.trim())?.[1] ?? cleanInline(rawType)).trim() || null : null;
  const dRaw = cleanInline(at("default"));
  const defaultValue = !dRaw || dRaw === "—" || dRaw === "-" ? null : dRaw.replace(/^'(.*)'$/, "$1").replace(/^"(.*)"$/, "$1");
  const desc = cleanInline(at("description"));
  return { name, type, defaultValue, required, description: desc || null, allowedValues: literalUnion(type) };
}

export function parseDocsMd(md: string): MdPage {
  const blocks = scanMarkdown(md);
  let title: string | null = null;
  let description: string | null = null;
  const sections: MdSection[] = [];
  const api: MdApiSection[] = [];
  const links = new Set<string>();
  const imports = new Set<string>();
  let cur: MdSection | null = null;
  let inApi = false;
  let apiOwner: string | null = null;
  let stop = false;
  for (const b of blocks) {
    if (b.type === "heading") {
      if (b.depth === 1) {
        if (!title) title = b.text;
        continue;
      }
      if (b.depth === 2) {
        inApi = /^api$/i.test(b.text);
        stop = /^related types$/i.test(b.text);
        apiOwner = null;
        cur = { title: b.text, depth: 2, firstParagraph: null, line: b.line, code: [] };
        sections.push(cur);
        continue;
      }
      if (inApi && b.depth === 3) apiOwner = b.text.replace(/[`*]/g, "").trim();
      else if (cur && b.depth === 3) {
        cur = { title: b.text, depth: 3, firstParagraph: null, line: b.line, code: [] };
        sections.push(cur);
      }
      continue;
    }
    if (b.type === "para") {
      for (const l of pageLinks(b.text)) links.add(l);
      if (!sections.length && title && !description) description = cleanInline(b.text);
      else if (cur && !cur.firstParagraph) cur.firstParagraph = cleanInline(b.text);
      continue;
    }
    if (b.type === "code") {
      for (const m of b.value.matchAll(/from\s+['"]([^'"]+)['"]/g)) imports.add(m[1]!);
      if (cur) cur.code.push({ lang: b.lang, value: b.value });
      continue;
    }
    if (b.type === "table" && inApi && !stop) {
      const h = b.header.map((x) => x.toLowerCase());
      if (!h.includes("name") || !h.includes("type")) continue;
      const props = b.rows.map((r) => readPropRow(b.header, r)).filter((p): p is MdProp => !!p);
      const name = apiOwner ?? title ?? "";
      if (name && props.length) api.push({ name, props, line: b.line });
    }
  }
  const callouts = inlineAlerts(md);
  return { title, description, sections, api, links: [...links].sort(), imports: [...imports].sort(), ...(callouts.length ? { callouts } : {}) };
}

/**
 * InlineAlert callouts (e.g. FileTrigger's "Accessibility" notice). The line scanner drops JSX blocks as
 * prose, so these are read separately; fenced code is skipped first.
 */
export function inlineAlerts(md: string): { title: string; text: string }[] {
  const prose = md.replace(/^([ \t]*)(```|~~~)[^\n]*\n[\s\S]*?\n\1\2[^\n]*$/gm, "");
  const out: { title: string; text: string }[] = [];
  for (const m of prose.matchAll(/<InlineAlert\b[^>]*>\s*<Heading>([\s\S]*?)<\/Heading>\s*<Content>([\s\S]*?)<\/Content>\s*<\/InlineAlert>/g)) {
    const title = cleanInline(m[1]!).trim();
    // Code spans are kept verbatim ("Any `<Pressable>` child" must not lose "<Pressable>").
    const text = collapse(
      m[2]!
        .split(/(`[^`]*`)/)
        .map((part) =>
          part.startsWith("`") && part.endsWith("`") && part.length > 1
            ? part.slice(1, -1)
            : part
                .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
                .replace(/\*\*([^*]+)\*\*/g, "$1")
                .replace(/<\/?[A-Za-z][^>]*>/g, ""),
        )
        .join(""),
    ).trim();
    if (title && text) out.push({ title, text });
  }
  return out;
}

/* ------------------------------ MDX metadata ------------------------------ */

export interface MdxMeta {
  version: string | null;
  description: string | null;
  tags: string[];
  relatedPages: { title: string; url: string }[];
  /** Export whose description is used as the page description (PageDescription). */
  primaryExport: string | null;
}

const q = `(?:'((?:[^'\\\\]|\\\\.)*)'|"((?:[^"\\\\]|\\\\.)*)")`;

export function parseMdxMeta(mdx: string): MdxMeta {
  const strExport = (name: string) => {
    const m = new RegExp(`^export\\s+const\\s+${name}\\s*=\\s*${q}\\s*;?`, "m").exec(mdx);
    return m ? (m[1] ?? m[2] ?? "").replace(/\\(['"])/g, "$1") : null;
  };
  const tagsM = /^export\s+const\s+tags\s*=\s*\[([^\]]*)\]/m.exec(mdx);
  const tags = tagsM ? [...tagsM[1]!.matchAll(new RegExp(q, "g"))].map((m) => m[1] ?? m[2] ?? "").filter(Boolean) : [];
  const relM = /^export\s+const\s+relatedPages\s*=\s*\[([\s\S]*?)\]\s*;?\s*$/m.exec(mdx);
  const relatedPages: { title: string; url: string }[] = [];
  if (relM) {
    const re = new RegExp(`\\{\\s*['"]?title['"]?\\s*:\\s*${q}\\s*,\\s*['"]?url['"]?\\s*:\\s*${q}\\s*\\}`, "g");
    for (const m of relM[1]!.matchAll(re)) relatedPages.push({ title: m[1] ?? m[2] ?? "", url: m[3] ?? m[4] ?? "" });
  }
  const pe = /<PageDescription>\s*\{\s*docs\.exports\.([A-Za-z0-9_]+)\.description\s*\}/.exec(mdx);
  return { version: strExport("version"), description: strExport("description"), tags, relatedPages, primaryExport: pe ? pe[1]! : null };
}
